def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--destination", default="PA194NS_research")
    parser.add_argument("--sources-only", action="store_true")
    args = parser.parse_args()
    manifest = json.loads(FILES["bundle_manifest.json"])["sha256"]
    for name, expected in manifest.items():
        actual = hashlib.sha256(FILES[name].encode("utf-8")).hexdigest()
        if actual != expected:
            raise SystemExit("Embedded source digest mismatch: " + name)
    root = Path(args.destination).expanduser().resolve()
    if root.exists():
        raise SystemExit("Destination already exists; choose a new directory: " + str(root))
    for name in FILES:
        relative = Path(name)
        if relative.is_absolute() or ".." in relative.parts:
            raise SystemExit("Unsafe embedded path: " + name)
    root.mkdir(parents=True, exist_ok=False)
    for name, content in FILES.items():
        target = root / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(content.encode("utf-8"))
    (root / "reconstruct.py").write_bytes(Path(__file__).read_bytes())
    print(f"Wrote {len(FILES)} preserved files and this bootstrap to {root}")
    if not args.sources_only:
        subprocess.run([sys.executable, str(root / "build.py")], cwd=root, check=True)
    else:
        print("Run python3 build.py in the destination when ready.")
if __name__ == "__main__":
    main()

